CREATE INDEX `idx_events_lifecycle` ON `events` (`conversation_id`,`type`,`seq`) WHERE "events"."type" in ('permission.requested', 'permission.resolved', 'question.requested', 'question.resolved', 'plan.review_requested', 'plan.review_resolved', 'elicitation.requested', 'elicitation.resolved', 'message.queued', 'message.dequeued', 'background.updated', 'task.completed', 'session.ended', 'turn.completed');